if.script:
const toNum = (v) => (v == null ? 0 : (typeof v === 'object' && typeof v.toNumber === 'function' ? v.toNumber() : (Number(v) || 0)));
function fmt(n) {
    return toNum(n).toLocaleString('it-IT', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
}
function fmtDt(d) {
    if (!d) return '—';
    try { return ec.l10n.format(d, 'dd/MM/yyyy'); } catch (e) { return String(d).slice(0, 10); }
}

const org = context.organization || {};
const bens = context.beneficiaries || [];
const yr = context.fiscalYear || new Date().getFullYear();
const nowFmt = ec.l10n.format(ec.user.nowTimestamp, 'dd/MM/yyyy HH:mm');

let h = `
<style>
    @page {
        size: A4 landscape;
        margin: 12mm 10mm 15mm 10mm;
        @top-right { content: "Withholding Tax Statement / Model 770 - Fiscal Year ${yr}"; font-size: 8pt; font-family: sans-serif; color: #555; }
        @bottom-right { content: "Page " counter(page); font-size: 8pt; font-family: sans-serif; color: #555; }
    }
    body { font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 8.5pt; color: #222; margin: 0; padding: 0; background: #fff; }
    .report-container { padding: 10px; }
    .header-box { border-bottom: 2px solid #000; padding-bottom: 6px; margin-bottom: 12px; display: flex; justify-content: space-between; }
    .company-name { font-size: 13pt; font-weight: bold; text-transform: uppercase; }
    .fiscal-info { font-size: 8pt; color: #444; margin-top: 2px; }
    .doc-title { font-size: 11pt; font-weight: bold; margin-top: 4px; color: #000; }
    table.rep-table { width: 100%; border-collapse: collapse; font-size: 8pt; margin-top: 8px; }
    table.rep-table th { background: #f0f0f0; border: 1px solid #777; padding: 5px 4px; font-weight: bold; text-align: left; }
    table.rep-table td { border: 1px solid #ddd; padding: 4px; vertical-align: top; }
    tr.totals-row td { background: #e2e8f0; font-weight: bold; border-top: 2px solid #000; }
    .text-right { text-align: right; }
    .text-center { text-align: center; }
    .sign-box { margin-top: 25px; border-top: 1px solid #000; padding-top: 10px; display: flex; justify-content: space-between; }
</style>
<div class="report-container">
    <div class="header-box">
        <div>
            <div class="company-name">${org.organizationName || organizationPartyId}</div>
            <div class="fiscal-info">
                VAT ID: <strong>${org.taxIdNumber || '—'}</strong> |
                Fiscal Code / SSN: <strong>${org.socialSecurityNumber || '—'}</strong> |
                R.E.A.: <strong>${org.reaNumber || '—'}</strong>
            </div>
            <div class="doc-title">WITHHOLDING TAX STATEMENT / SINGLE CERTIFICATION (Model 770)</div>
        </div>
        <div style="text-align: right;">
            <div style="font-size: 10pt; font-weight: bold;">FISCAL YEAR: ${yr}</div>
            <div style="font-size: 8pt; color: #666; margin-top: 4px;">Issue date: ${nowFmt}</div>
        </div>
    </div>

    <table class="rep-table">
        <thead>
            <tr>
                <th>Beneficiary (Professional / Agent)</th>
                <th style="width: 110px;">Fiscal Code</th>
                <th style="width: 95px;">VAT ID</th>
                <th style="width: 55px;" class="text-center">Reason</th>
                <th style="width: 60px;" class="text-center">F24 Code</th>
                <th style="width: 85px;" class="text-right">Gross Amount</th>
                <th style="width: 75px;" class="text-right">Non-Taxable</th>
                <th style="width: 85px;" class="text-right">Taxable Base</th>
                <th style="width: 85px;" class="text-right">Withholding Tax</th>
                <th style="width: 85px;" class="text-right">Net Paid</th>
            </tr>
        </thead>
        <tbody>`;

if (bens.length === 0) {
    h += `<tr><td colspan="10" style="text-align: center; padding: 25px; color: #666;">
        No invoices with withholding tax registered for fiscal year ${yr}.
    </td></tr>`;
}

for (const b of bens) {
    h += `<tr>
        <td><strong>${b.beneficiaryName}</strong></td>
        <td><code>${b.fiscalCode || '—'}</code></td>
        <td>${b.vatNumber || '—'}</td>
        <td class="text-center"><strong>${b.paymentReason}</strong></td>
        <td class="text-center"><strong>${b.f24TaxCode}</strong></td>
        <td class="text-right">${fmt(b.grossAmount)}</td>
        <td class="text-right">${fmt(b.nonTaxableAmount)}</td>
        <td class="text-right">${fmt(b.taxableAmount)}</td>
        <td class="text-right" style="color: #dc2626; font-weight: bold;">${fmt(b.withheldAmount)}</td>
        <td class="text-right"><strong>${fmt(b.netAmount)}</strong></td>
    </tr>`;
}

h += `<tr class="totals-row">
    <td colspan="5" class="text-right">GENERAL TOTALS:</td>
    <td class="text-right">${fmt(context.totalGrossAmount)}</td>
    <td class="text-right">${fmt(context.totalNonTaxableAmount)}</td>
    <td class="text-right">${fmt(context.totalTaxableAmount)}</td>
    <td class="text-right" style="color: #dc2626;">${fmt(context.totalWithheldAmount)}</td>
    <td class="text-right">${fmt(context.totalNetAmount)}</td>
</tr>
</tbody>
</table>

<div class="sign-box">
    <div>
        Total Certified Beneficiaries: <strong>${bens.length}</strong> |
        Total Invoices/Parcels: <strong>${context.totalInvoicesCount || 0}</strong>
    </div>
    <div style="text-align: right;">
        <div>Signature of Withholding Agent: ___________________________</div>
    </div>
</div>
</div>`;

context.printHtml = h;
